ALTER TABLE public.telegram_offers ADD COLUMN confirmation_chat_id text;
CREATE OR REPLACE FUNCTION public.telegram_cancel_unlinked_deliveries() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.telegram_deliveries SET status='cancelled',error_code='LINK_REVOKED' WHERE website_user_id=OLD.website_user_id AND chat_id=OLD.telegram_user_id AND status='pending'; RETURN OLD; END; $$;
CREATE TRIGGER telegram_link_revoked AFTER DELETE ON public.telegram_account_links FOR EACH ROW EXECUTE FUNCTION public.telegram_cancel_unlinked_deliveries();
CREATE OR REPLACE FUNCTION public.telegram_claim_delivery(_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.telegram_deliveries; BEGIN SELECT * INTO d FROM public.telegram_deliveries WHERE id=_id FOR UPDATE; IF d.id IS NULL OR d.status<>'pending' THEN RETURN false; END IF; IF d.website_user_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.telegram_account_links l WHERE l.telegram_user_id=d.chat_id AND l.website_user_id=d.website_user_id AND (d.dedupe_key NOT LIKE 'broadcast:%' OR l.notify_announcements) AND (d.dedupe_key NOT LIKE 'generation:%' AND d.dedupe_key NOT LIKE 'payment:%' OR l.notify_account)) THEN UPDATE public.telegram_deliveries SET status='cancelled',error_code='LINK_OR_CONSENT_REVOKED' WHERE id=_id; RETURN false; END IF; UPDATE public.telegram_deliveries SET status='sending',attempts=attempts+1 WHERE id=_id; RETURN true; END; $$;
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.telegram_confirm_offer(uuid,text,text,boolean)'::regprocedure) INTO d; d:=replace(d,'IF o.id IS NULL OR o.owner_id<>c.website_owner_id THEN','IF o.id IS NULL OR o.owner_id<>c.website_owner_id OR o.confirmation_chat_id IS DISTINCT FROM _chat THEN'); d:=replace(d,'INSERT INTO public.admin_audit_log(admin_id,action,target_user,reason,related_id,details) VALUES(c.website_owner_id,''telegram_custom_offer''','INSERT INTO public.telegram_deliveries(dedupe_key,chat_id,message,website_user_id,delivery_method,payload) SELECT ''offer:''||o.id::text,l.telegram_user_id,o.name||E''\n₹''||(o.amount_paise/100.0)||'' · ''||o.credits||'' credits · ''||o.days||'' days · ''||o.tier||E''\nOrder: ''||ord||E''\nSend /utr ''||ord||'' <12-digit UTR> privately. Owner must verify actual bank receipt before activation.'',o.user_id,''sendPhoto'',jsonb_build_object(''photo'',c.original_qr_file_id) FROM public.telegram_account_links l WHERE l.website_user_id=o.user_id ON CONFLICT DO NOTHING; INSERT INTO public.admin_audit_log(admin_id,action,target_user,reason,related_id,details) VALUES(c.website_owner_id,''telegram_custom_offer'''); EXECUTE d; END; $$;
REVOKE ALL ON FUNCTION public.telegram_claim_delivery(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.telegram_claim_delivery(uuid) TO service_role;